import{_ as e,o as n,c as o,a5 as i}from"./chunks/framework.CXroN2RO.js";const h=JSON.parse('{"title":"ECS — Entity Component System","description":"EntityのIDと寿命、Componentの配置、Query、構成変更、並列実行と性能判断を説明します。","frontmatter":{"title":"ECS — Entity Component System","description":"EntityのIDと寿命、Componentの配置、Query、構成変更、並列実行と性能判断を説明します。","study":{"source":"新規執筆","kind":"本文草稿","status":"草稿","summary":"EntityのIDと寿命、Componentの配置、Query、構成変更、並列実行と性能判断を説明します。"}},"headers":[],"relativePath":"game/ecs.md","filePath":"game/ecs.md"}'),r={name:"game/ecs.md"};function a(s,t,d,l,c,p){return n(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="ecs-—-entity-component-system" tabindex="-1">ECS — Entity Component System <a class="header-anchor" href="#ecs-—-entity-component-system" aria-label="Permalink to &quot;ECS — Entity Component System&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">草稿と検証範囲</p><p>公式資料を照合。数値・配置の例は説明モデル、コードは擬似コード。Unity/EnTTのプロジェクト実行は未実施。</p><p>資料の参照日：2026-10-30。実装の実行検証日を示すものではありません。</p></div><h2 id="basics" tabindex="-1">1. ECSとは何か <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;1. ECSとは何か {#basics}&quot;">​</a></h2><p>Entity・Component・System、WorldとRegistry、Component方式との違い</p><div class="study-source-prose"><p><strong>ECS（Entity Component System）は、対象の同一性、対象のデータ、そのデータを処理する規則を分けて組み立てる設計です。</strong>例えば「敵」という継承クラスだけで能力を決めず、Position・Velocity・Healthなどの組合せと、それを処理するSystemで表します。</p><div class="scroll"><table><thead><tr><th>用語</th><th>役割</th><th>移動する対象の例</th></tr></thead><tbody><tr><td>Entity</td><td>何を扱うかを識別する</td><td>E7というハンドル。Positionそのもののアドレスではない</td></tr><tr><td>Component</td><td>Entityに結び付く型付きのデータ</td><td>Position{x,y}、Velocity{dx,dy}、Health{hp}</td></tr><tr><td>System</td><td>必要なデータを選んで処理する規則</td><td>PositionとVelocityのある対象を移動させる</td></tr><tr><td>World / Registry</td><td>EntityとComponentの集合・管理の範囲</td><td>ゲーム本編、プレビュー、テスト等の管理単位。呼称と機能は実装による</td></tr><tr><td>Query / View</td><td>対象をComponentの条件から選ぶ</td><td>PositionかつVelocityを持ち、Frozenを持たない対象</td></tr></tbody></table></div><p>Componentに補助メソッドを置けない、System自身が設定やキャッシュを持てない、という言語上の禁止ではありません。対象ごとの状態と、多数の対象へ適用する処理を分けて考える点が中心です。<span class="source"><a target="_blank" rel="noopener noreferrer" href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/concepts-intro.html">Unity Entities 1.0.16: ECS concepts</a></span></p><p>GameObjectへ振る舞いの部品を付けるComponent方式も、ECSも、機能の組合せを扱います。部品ごとにUpdateを呼ぶ方式と、データをQueryで選び横断処理する方式には違いがありますが、性能や柔軟性を二者択一で分ける定義にはしません。</p></div><h2 id="identity" tabindex="-1">2. EntityのIDと寿命 <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;2. EntityのIDと寿命 {#identity}&quot;">​</a></h2><p>世代付きハンドル、Worldの所属、格納位置と同一性、保存時のID</p><div class="study-source-prose"><p>Entityは「今どの行へ格納されているか」と別に識別します。削除や構成変更でデータが動いても、同じEntityを追えるようにするためです。UnityでもEntityはComponentを関連付けるIDとして扱われます。<span class="source"><a target="_blank" rel="noopener noreferrer" href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/concepts-entities.html">Unity Entities 1.0.16: Entities</a></span></p><p>世代付きハンドルの説明モデルでは、<code>{slot:7, generation:3}</code>を持つ対象を破棄した後、同じslotをgeneration 4で再利用します。古いハンドルを検証すると世代の不一致を検出できます。EnTTも識別子にversionを持ちます。<span class="source"><a target="_blank" rel="noopener noreferrer" href="https://github.com/skypjack/entt/wiki/Entity-Component-System">EnTT：Entityの識別子とversion</a></span></p><div class="scroll"><table><thead><tr><th>持っているもの</th><th>何を確認するか</th></tr></thead><tbody><tr><td>Entityハンドル</td><td>所属World/Registryと生存・世代。別Worldで同じ数値でも同じ対象とは限らない</td></tr><tr><td>Componentへの参照・ポインタ</td><td>削除・再配置・ストレージ方針による有効期間。Entityが生存していても参照は別に失効し得る</td></tr><tr><td>配列の行番号</td><td>現在の格納位置。swap-and-popで別のEntityが入ることがある</td></tr><tr><td>セーブ・通信での永続ID</td><td>再起動やWorld再構築を越える識別規約と、実行時ハンドルへの対応表</td></tr></tbody></table></div><p class="note">世代カウンタも有限です。ビット数、周回時の扱い、有効性検査は実装の契約を確認します。実行時Entityの数値を、そのまま永続的な作品内IDにする前提にはしません。</p></div><h2 id="storage" tabindex="-1">3. データはどこに置かれるか <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;3. データはどこに置かれるか {#storage}&quot;">​</a></h2><p>Archetype・Chunk・Sparse Set、AoS/SoA、局所性と間接参照</p><div class="study-source-prose"><p><strong>ArchetypeはComponent型の組合せです。</strong>Position+VelocityとPosition+Velocity+Healthは別の組合せになります。Unity Entitiesは同じ組合せをChunkへ収め、Chunk内で型ごとのデータをまとめます。下の表は配置を説明する模式図です。<span class="source"><a target="_blank" rel="noopener noreferrer" href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/concepts-archetypes.html">Unity Entities 1.0.16: Archetypes and chunks</a></span></p><div class="scroll"><table><thead><tr><th>Archetype</th><th>Entityの列</th><th>Positionの列</th><th>Velocityの列</th><th>Healthの列</th></tr></thead><tbody><tr><td>A: Position + Velocity</td><td>E7, E9</td><td>P7, P9</td><td>V7, V9</td><td>なし</td></tr><tr><td>B: Position + Velocity + Health</td><td>E2</td><td>P2</td><td>V2</td><td>H2</td></tr><tr><td>C: Position</td><td>E5</td><td>P5</td><td>なし</td><td>なし</td></tr></tbody></table></div><p>同じChunk・同じ行なら、そのEntityの各Componentが対応します。Archetype全体が一つの巨大な配列になるとは限らず、実際には複数のChunk等に分かれます。またPositionの配列があっても、その内部のxとyまで別々の配列になるとは限りません。ECS、Component単位の配列化、フィールド単位のSoAは区別します。</p><p><strong>Sparse Set型</strong>の説明モデルでは、Component型ごとに「詰めたデータ列・対応するEntity列・Entityから位置を引く疎な索引」を持ちます。複数型をまたぐ処理では所属を照合します。Position列の3番とVelocity列の3番が、同じEntityである保証は一般にはありません。EnTTはこの系統ですが、ページ化やGroupなどの工夫もあります。<span class="source"><a target="_blank" rel="noopener noreferrer" href="https://github.com/skypjack/entt/wiki/Entity-Component-System">EnTT：Sparse Set、Storage、Views / Groups</a></span></p><div class="scroll"><table><thead><tr><th>比較軸</th><th>Archetype型で考えること</th><th>Sparse Set型で考えること</th></tr></thead><tbody><tr><td>走査</td><td>条件に合う型の組合せと、その中の列を走査</td><td>各型の所属を照合。View/Group等の方針も影響</td></tr><tr><td>構成変更</td><td>別の組合せへの移動やChunk確保が起こり得る</td><td>関係する型のPoolへの追加・削除と索引更新</td></tr><tr><td>メモリ</td><td>Componentの大きさ、Chunkの空き、組合せの細分化</td><td>疎な索引、ページ、詰め方と安定性の方針</td></tr><tr><td>得失の判断</td><td>走査量・構成変更量・関係参照で比較</td><td>同じ負荷で比較。方式名だけで優劣を決めない</td></tr></tbody></table></div></div><h2 id="query" tabindex="-1">4. Queryと一括処理 <a class="header-anchor" href="#query" aria-label="Permalink to &quot;4. Queryと一括処理 {#query}&quot;">​</a></h2><p>Componentの組合せ、条件に一致するEntity、読み書きの宣言</p><div class="study-source-prose"><p>移動Systemの条件を「PositionとVelocityがある」とすると、上のA・Bが対象で、Cは対象外です。Healthを持つかどうかは、この移動条件には影響しません。キャラクターのクラス名ではなく、必要なデータから対象を選びます。</p><pre><code>// 処理の意味を示す擬似コード。特定ライブラリのAPIではない。
for each entity matching (Position, Velocity) and not Frozen:
    position = write Position of entity
    velocity = read Velocity of entity
    position.x += velocity.dx * dt
    position.y += velocity.dy * dt</code></pre><p>Position=(1,2)、Velocity=(4,-2)、dt=0.5なら、更新後は(3,1)です。実装では、どのComponentを読むか・書くかも宣言します。Queryの型条件と、有効/無効・共有値・変更検知等の追加フィルタは、使う実装の規則に従います。</p><p>Entityごとに全Componentを探す、全Entityを毎回走査する、条件に合うArchetypeやPoolを再利用する、では仕事量が異なります。Queryを作ったことと、検索・列挙のコストがゼロになることは同じではありません。既存の並行配列の最小例は、全対象が同じ構成という条件下の一括処理を示す教材です。</p></div><h2 id="structural" tabindex="-1">5. Componentを追加すると内部で何が起きるか <a class="header-anchor" href="#structural" aria-label="Permalink to &quot;5. Componentを追加すると内部で何が起きるか {#structural}&quot;">​</a></h2><p>構成変更、データ移動、格納位置表、swap-and-pop、参照の無効化</p><div class="study-source-prose"><p><strong>値の更新</strong>と<strong>Component構成の変更</strong>を分けます。既に持っているPositionのxを書き換えることと、Health型を新しく付けることは、同じ処理ではありません。</p><p>Archetype型でE7へHealthを追加する場合、内部は例えば次のように進みます。これは一般的な仕組みを理解するための説明モデルであり、全ライブラリの実装手順を固定するものではありません。</p><ol class="ecs-flow"><li><strong>対象を検証</strong><br>E7の所属と生存を確認し、現在の格納位置を調べる。</li><li><strong>移動先を決める</strong><br>Position+Velocity+HealthのArchetypeと空き領域を探す。必要なら領域を確保する。</li><li><strong>データを移す</strong><br>共通のPosition/Velocityを引き継ぎ、新しいHealthを初期化する。</li><li><strong>位置表を更新</strong><br>E7から新しい格納先を引けるようにする。</li><li><strong>元の隙間を扱う</strong><br>詰める方式なら別のEntityを移動し、そのEntityの位置表も更新する。</li></ol><div class="scroll"><table><thead><tr><th>タイミング</th><th>Archetype A</th><th>Archetype B</th><th>E7の同一性</th></tr></thead><tbody><tr><td>追加前</td><td>E7, E9</td><td>E2</td><td>E7はAの先頭にいる</td></tr><tr><td>Health追加後の一例</td><td>E9</td><td>E2, E7</td><td>E7は同じ対象のまま、格納先がBへ変わる</td></tr></tbody></table></div><p>Unity Entitiesでは生成・破棄、Component追加/削除、Shared Component値の変更がStructural Changeに含まれます。Entities 1.0.16では、構造変更後のComponentへの直接参照は無効として取り直します。通常の値更新とは別の契約です。<span class="source"><a target="_blank" rel="noopener noreferrer" href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/concepts-structural-changes.html">Unity Entities 1.0.16: Structural changes</a></span></p><p>削除で末尾の要素を空きへ移すswap-and-popは順序を保ちません。アドレスやイテレータの安定性はストレージの契約次第なので、参照をフレームを越えて保持する前に確認します。全実装について「追加だけで必ず全参照が無効」「削除しても必ず安定」とは決められません。</p><p>UnityのEnableable Componentは、有効状態の変更で構造変更を避ける選択肢です。無効なComponentは通常のQueryの一致判定から外れますが、型自体がEntityから削除されたわけではありません。<span class="source"><a target="_blank" rel="noopener noreferrer" href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/components-enableable-intro.html">Unity Entities 1.0.16: Enableable components</a></span></p></div><h2 id="execution" tabindex="-1">6. 更新順序・並列実行・変更の予約 <a class="header-anchor" href="#execution" aria-label="Permalink to &quot;6. 更新順序・並列実行・変更の予約 {#execution}&quot;">​</a></h2><p>依存グラフ、競合、Command Buffer、Playback、決定性</p><div class="study-source-prose"><p>Systemの更新順は、ゲームの意味とデータ依存から決めます。移動後の位置を使って当たり判定するなら、その前後関係が必要です。「Systemを別のファイルへ分けた」だけでは、順序も並列実行も保証されません。</p><div class="scroll"><table><thead><tr><th>System例</th><th>読む</th><th>書く</th><th>依存の例</th></tr></thead><tbody><tr><td>Move</td><td>Velocity</td><td>Position</td><td>Positionを読む処理は、この書込み完了との依存を考える</td></tr><tr><td>Collision</td><td>Position / Collider</td><td>Contact</td><td>この例ではMove後の位置を使う</td></tr><tr><td>Damage</td><td>Contact</td><td>Health</td><td>Collisionの結果を待つ</td></tr><tr><td>Animate</td><td>AnimationState</td><td>Pose</td><td>上の系統と独立なら並列化候補。共有資源も確認</td></tr></tbody></table></div><p>読み取り同士は共有しやすく、同じデータへの書込みが重なる処理には順序付け等が必要です。型単位の依存管理だけで、外部の配列・グローバル状態・別Entityへの書込みまで全て検出できるとは限りません。UnityのJob依存にも、外部NativeArray等の依存を自分で接続する場面があります。<span class="source"><a target="_blank" rel="noopener noreferrer" href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/scheduling-jobs-dependencies.html">Unity Entities 1.0.16: Job dependencies</a></span></p><p>Systemの更新関数を呼ぶ順番と、その関数から予約したJobが完了する順番も別です。先のSystemの更新関数が戻っていても、Jobは実行中かもしれません。後続のJobへ完了依存を渡すことと、メインスレッドで結果を使う前に必要な完了を待つことを区別します。</p><h3>Command Buffer：変更の予約と適用を分ける</h3><p>走査中に対象の配置を変えると、走査中の参照や範囲へ影響します。変更要求を記録し、安全な境界で適用する方法がCommand Bufferです。UnityのECBも記録とPlaybackを分けます。予約した時点と、Worldへ反映された時点は別です。<span class="source"><a target="_blank" rel="noopener noreferrer" href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/systems-entity-command-buffers.html">Unity Entities 1.0.16: Entity command buffers</a></span></p><pre><code>// 擬似コード：破棄を予約してから適用するモデル
for each entity matching Lifetime:
    lifetime.remaining -= dt
    if lifetime.remaining &lt;= 0:
        commands.destroy(entity)   // この行で直ちに配置を変えない

wait for jobs that use the affected data
commands.playback(world)           // 定めた境界で適用
reacquire component references as required</code></pre><p>Command Bufferにしても、移動・破棄・確保のコストが消えるわけではありません。どのフレームのどの境界で適用するかを決めます。許可される走査中の操作は実装によって異なります。</p><p><strong>ECSだけでは決定性も保証されません。</strong>入力を適用するtick、時間刻み、乱数と使用順、SystemとEntityの処理順、並列実行、浮動小数点条件、外部I/Oを含めて、再現したい範囲を設計します。</p></div><h2 id="engines" tabindex="-1">7. Unityなどの実装との関係 <a class="header-anchor" href="#engines" aria-label="Permalink to &quot;7. Unityなどの実装との関係 {#engines}&quot;">​</a></h2><p>GameObject/MonoBehaviour、Entities、Jobs、Burst、Baking、EnTT</p><div class="study-source-prose"><div class="scroll"><table><thead><tr><th>用語・仕組み</th><th>役割</th><th>区別したい点</th></tr></thead><tbody><tr><td>GameObject / MonoBehaviour</td><td>オブジェクトへComponentを付けるUnityの方式</td><td>名称にComponentがあっても、Entitiesの格納・Queryモデルと同じではない</td></tr><tr><td>Unity Entities</td><td>World・Entity・Component・Systemを管理するECSの実装</td><td>この章のUnity固有の挙動はEntities 1.0.16資料を参照</td></tr><tr><td>C# Job System</td><td>仕事の実行と依存を扱う</td><td>ECSというデータモデルと、仕事を並列に実行する仕組みは別</td></tr><tr><td>Burst</td><td>対応する処理をコンパイルする仕組み</td><td>ECSそのものでも、全処理が自動的に対象になる機能でもない</td></tr><tr><td>Authoring / Baking</td><td>制作時の表現から実行時データへつなぐ工程</td><td>GameObjectの見た目の構成と、実行時Entity構成を一対一と決めない</td></tr><tr><td>EnTT</td><td>C++のEntity/Component管理、Storage・View/Group等</td><td>UnityのChunk配置や更新スケジューラの説明をそのまま一般化しない</td></tr></tbody></table></div><p>Unityの用語は<a target="_blank" rel="noopener noreferrer" href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/concepts-intro.html">Unity Entities 1.0.16: ECS concepts</a>、制作時データの変換は<a target="_blank" rel="noopener noreferrer" href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/baking-overview.html">Unity Entities 1.0.16: Baking overview</a>、コンパイル対象は<a target="_blank" rel="noopener noreferrer" href="https://docs.unity3d.com/Packages/com.unity.burst@1.8/manual/index.html">Unity Burst 1.8: Burst compiler</a>、EnTTの管理とStorageは<a target="_blank" rel="noopener noreferrer" href="https://github.com/skypjack/entt/wiki/Entity-Component-System">EnTT: Entity Component System — storage, views, entity versions</a>を参照。実装例を書くときはEditor・Entities・Collections・BurstやC++ライブラリの版を揃えます。</p><p>例えば大量の弾の移動をECSへ、個別の会話UIをGameObject側へ置く、といった併用も設計候補です。その場合は、どちらが状態の正本を持つか、データを渡すタイミング、生成・破棄の対応、描画や物理との同期を決めます。両側で同じ状態を独立に更新すると、整合性の問題が増えます。</p></div><h2 id="decisions" tabindex="-1">8. 採用の判断と性能の調べ方 <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;8. 採用の判断と性能の調べ方 {#decisions}&quot;">​</a></h2><p>得失、併用、デバッグ、構成変更の回数、待機と計測</p><div class="study-source-prose"><p>検討しやすいのは、同じデータに同じ処理を繰り返す負荷が大きい場合や、機能の組合せをデータで管理したい場合です。少数の複雑な対象でも採用は可能ですが、移行・デバッグ・制作工程・他システムとの接続の負担と釣り合わせます。採用する個数の境界は、固定の「何体以上」で決まりません。</p><div class="scroll"><table><thead><tr><th>観察するもの</th><th>理由</th></tr></thead><tbody><tr><td>System別のCPU時間、待機時間、走査する件数</td><td>仕事が重いのか、依存待ちなのかを分ける</td></tr><tr><td>構成変更の回数・移動量・Playback時間</td><td>毎フレームのadd/removeが走査の利点を消していないか</td></tr><tr><td>Componentの大きさ・Chunk/Poolの使用量</td><td>使わないデータ、空き、索引、外部参照のコストを見る</td></tr><tr><td>Entity間のランダム参照・階層の巡回</td><td>配列に置いても、その読み方によって局所性が変わる</td></tr><tr><td>Jobの粒度・並列度・共有データ</td><td>分割と同期のコスト、競合やfalse sharingを調べる</td></tr><tr><td>同じ入力・仕事量・実行条件での比較</td><td>ECS化と同時に別のアルゴリズムや機能まで変えた影響を分ける</td></tr></tbody></table></div><p>ECSは配列を使うだけの最適化手法でも、オブジェクト指向を禁止する規則でもありません。型・責務・データ配置・実行の境界を整理し、得られる柔軟性や処理効率と、管理のコストを観察するための設計です。</p></div><h2 id="labs" tabindex="-1">9. 手元で確かめる <a class="header-anchor" href="#labs" aria-label="Permalink to &quot;9. 手元で確かめる {#labs}&quot;">​</a></h2><p>Query・格納位置・寿命・構成変更・計測の小さな課題</p><div class="study-source-prose"><ol><li>Positionだけの対象、Position+Velocityの対象、さらにHealthを持つ対象を作り、移動Queryに含まれるものを予想して確認する。</li><li>EntityへHealthを追加する前後で、EntityのID、格納位置、保持していたComponent参照の扱いを調べる。実装の参照安定性の契約も読む。</li><li>破棄したハンドルを保持してslotを再利用し、有効性検査と世代の変化を確認する。別Worldのハンドルも混ぜずに扱う。</li><li>即時の構成変更と、変更要求をまとめたPlaybackを同じ負荷で比較し、移動量と待機を測る。</li><li>Systemの実行順と読み書きを図にし、並列化できる候補、別Entityや外部配列への依存を洗い出す。</li><li>同じ入力で実行した状態をtickごとに比較する。処理順を変え、ECSという方式と決定性の成立条件を分けて説明する。</li></ol><div class="callout"><strong>関連する読み物</strong><p><a href="/study/game/patterns/component-and-ecs.html">ComponentとECS</a>では部品方式との比較を、<a href="/study/samples/cpp/ecs_minimal.cpp">最小C++サンプル</a>では同じComponent構成の並行配列を処理する例を扱います。<a href="/study/guide/low-level/engine-architecture-ecs.html">ゲームエンジンアーキテクチャとECS</a>も併せて参照できます。</p></div><p>関連する分野：<a href="/study/runtime/">確保とアロケータ</a> / <a href="/study/guide/learning-paths.html">学習経路と関連分野</a> / <a href="/study/">ゲーム・言語・OSの分野索引</a>。</p></div><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><p><a href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/concepts-intro.html" target="_blank" rel="noreferrer">Unity Entities 1.0.16: ECS concepts</a></p></li><li><p><a href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/concepts-entities.html" target="_blank" rel="noreferrer">Unity Entities 1.0.16: Entities</a></p></li><li><p><a href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/concepts-archetypes.html" target="_blank" rel="noreferrer">Unity Entities 1.0.16: Archetypes and chunks</a></p></li><li><p><a href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/concepts-structural-changes.html" target="_blank" rel="noreferrer">Unity Entities 1.0.16: Structural changes</a></p></li><li><p><a href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/systems-entity-command-buffers.html" target="_blank" rel="noreferrer">Unity Entities 1.0.16: Entity command buffers</a></p></li><li><p><a href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/scheduling-jobs-dependencies.html" target="_blank" rel="noreferrer">Unity Entities 1.0.16: Job dependencies</a></p></li><li><p><a href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/components-enableable-intro.html" target="_blank" rel="noreferrer">Unity Entities 1.0.16: Enableable components</a></p></li><li><p><a href="https://docs.unity3d.com/Packages/com.unity.entities@1.0/manual/baking-overview.html" target="_blank" rel="noreferrer">Unity Entities 1.0.16: Baking overview</a></p></li><li><p><a href="https://docs.unity3d.com/Packages/com.unity.burst@1.8/manual/index.html" target="_blank" rel="noreferrer">Unity Burst 1.8: Burst compiler</a></p></li><li><p><a href="https://github.com/skypjack/entt/wiki/Entity-Component-System" target="_blank" rel="noreferrer">EnTT: Entity Component System — storage, views, entity versions</a></p></li></ul>`,31)])])}const m=e(r,[["render",a]]);export{h as __pageData,m as default};
